-- Insert the staged rows that the target lacks. A short staging table means that
-- a batch above failed (sqlcmd without -b goes on): then nothing is inserted.
DECLARE @total int = (SELECT COUNT(*) FROM #u2_items);
DECLARE @inserted int;

IF @total <> 35860
BEGIN
    RAISERROR(N'#u2_items has %d rows, expected 35860; nothing inserted', 16, 1, @total);
    RETURN;
END

BEGIN TRANSACTION;

-- Record the ids that are about to be inserted.
INSERT INTO dbo.$(Target)_U2_ADDED (Num)
SELECT s.Num
FROM #u2_items AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(Target) AS t WHERE t.Num = s.Num)
  AND NOT EXISTS (SELECT 1 FROM dbo.$(Target)_U2_ADDED AS a WHERE a.Num = s.Num);

-- Insert only the ids that the target does not have.
INSERT INTO dbo.$(Target) (
    Num, strName, Kind, Slot, Race, Class, Damage, Delay, Range, Weight, Duration,
    BuyPrice, SellPrice, Ac, Countable, Effect1, Effect2, ReqLevel, ReqLevelMax,
    ReqRank, ReqTitle, ReqStr, ReqSta, ReqDex, ReqIntel, ReqCha, SellingGroup, ItemType,
    Hitrate, Evasionrate, DaggerAc, SwordAc, MaceAc, AxeAc, SpearAc, BowAc, FireDamage,
    IceDamage, LightningDamage, PoisonDamage, HPDrain, MPDamage, MPDrain, MirrorDamage,
    Droprate, StrB, StaB, DexB, IntelB, ChaB, MaxHpB, MaxMpB, FireR, ColdR, LightningR,
    MagicR, PoisonR, CurseR, ItemClass, ItemExt
)
SELECT
    Num, strName, Kind, Slot, Race, Class, Damage, Delay, Range, Weight, Duration,
    BuyPrice, SellPrice, Ac, Countable, Effect1, Effect2, ReqLevel, ReqLevelMax,
    ReqRank, ReqTitle, ReqStr, ReqSta, ReqDex, ReqIntel, ReqCha, SellingGroup, ItemType,
    Hitrate, Evasionrate, DaggerAc, SwordAc, MaceAc, AxeAc, SpearAc, BowAc, FireDamage,
    IceDamage, LightningDamage, PoisonDamage, HPDrain, MPDamage, MPDrain, MirrorDamage,
    Droprate, StrB, StaB, DexB, IntelB, ChaB, MaxHpB, MaxMpB, FireR, ColdR, LightningR,
    MagicR, PoisonR, CurseR, ItemClass, ItemExt
FROM #u2_items AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(Target) AS t WHERE t.Num = s.Num);

SET @inserted = @@ROWCOUNT;

COMMIT TRANSACTION;

PRINT 'inserted=' + CAST(@inserted AS varchar(10))
    + ' already_present=' + CAST(@total - @inserted AS varchar(10));
GO

-- Verification: row count of the target, ids in the log table, and staged rows
-- that are not in the target with exactly these values (0 after a clean run).
DECLARE @rows int = (SELECT COUNT(*) FROM dbo.$(Target));
DECLARE @logged int = (SELECT COUNT(*) FROM dbo.$(Target)_U2_ADDED);
DECLARE @differ int = (SELECT COUNT(*) FROM (
    SELECT
        Num, strName, Kind, Slot, Race, Class, Damage, Delay, Range, Weight, Duration,
        BuyPrice, SellPrice, Ac, Countable, Effect1, Effect2, ReqLevel, ReqLevelMax,
        ReqRank, ReqTitle, ReqStr, ReqSta, ReqDex, ReqIntel, ReqCha, SellingGroup,
        ItemType, Hitrate, Evasionrate, DaggerAc, SwordAc, MaceAc, AxeAc, SpearAc,
        BowAc, FireDamage, IceDamage, LightningDamage, PoisonDamage, HPDrain, MPDamage,
        MPDrain, MirrorDamage, Droprate, StrB, StaB, DexB, IntelB, ChaB, MaxHpB, MaxMpB,
        FireR, ColdR, LightningR, MagicR, PoisonR, CurseR, ItemClass, ItemExt
    FROM #u2_items
    EXCEPT
    SELECT
        Num, strName, Kind, Slot, Race, Class, Damage, Delay, Range, Weight, Duration,
        BuyPrice, SellPrice, Ac, Countable, Effect1, Effect2, ReqLevel, ReqLevelMax,
        ReqRank, ReqTitle, ReqStr, ReqSta, ReqDex, ReqIntel, ReqCha, SellingGroup,
        ItemType, Hitrate, Evasionrate, DaggerAc, SwordAc, MaceAc, AxeAc, SpearAc,
        BowAc, FireDamage, IceDamage, LightningDamage, PoisonDamage, HPDrain, MPDamage,
        MPDrain, MirrorDamage, Droprate, StrB, StaB, DexB, IntelB, ChaB, MaxHpB, MaxMpB,
        FireR, ColdR, LightningR, MagicR, PoisonR, CurseR, ItemClass, ItemExt
    FROM dbo.$(Target)) AS d);
PRINT 'target_rows=' + CAST(@rows AS varchar(10))
    + ' logged=' + CAST(@logged AS varchar(10))
    + ' staged_not_in_target=' + CAST(@differ AS varchar(10));

DROP TABLE #u2_items;
GO
